Use a subcommand with flags:

```bash
booklist add --title "The Hobbit" --author "J.R.R. Tolkien" --status to-read
```

Example Go handler:

```go
func addBook(args []string, books *[]Book) error {
	fs := flag.NewFlagSet("add", flag.ExitOnError)

	title := fs.String("title", "", "Book title")
	author := fs.String("author", "", "Book author")
	status := fs.String("status", "to-read", "to-read, reading, or finished")

	fs.Parse(args)

	if *title == "" || *author == "" {
		return errors.New("title and author are required")
	}

	if *status != "to-read" && *status != "reading" && *status != "finished" {
		return errors.New("invalid status")
	}

	*books = append(*books, Book{
		ID:     nextID(*books),
		Title:  *title,
		Author: *author,
		Status: *status,
	})

	return nil
}
```

Then save the updated slice to your JSON file.

```go
func LoadBooks(path string) ([]Book, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return []Book{}, nil // Start with an empty list.
		}
		return nil, err
	}

	var books []Book
	if err := json.Unmarshal(data, &books); err != nil {
		return nil, fmt.Errorf("decode books file: %w", err)
	}

	return books, nil
}
```

Imports:

```go
import (
	"encoding/json"
	"errors"
	"fmt"
	"os"
)
```

A missing file is treated as an empty list; other file or JSON errors are returned.

